  "prereqHtml": "способность создавать или контролировать <a class=\"item-link quicklink link--popup item-link--trait\" data-key=\"trait/722\" href=\"https://pf2.ru/traits/undead\">Нежить</a>; <a class=\"item-link quicklink link--popup item-link--class_\" data-key=\"class_/33\" href=\"https://pf2.ru/classes/cleric?tab=details\">жрец</a> с негативной купелью, <a class=\"item-link quicklink link--popup item-link--class_\" data-key=\"class_/61\" href=\"https://pf2.ru/classes/oracle?tab=details\">оракул</a> <a class=\"item-link quicklink item-link--oraclemystery\" data-key=\"oraclemystery/14\" href=\"https://pf2.ru/oraclemysteries/bones\">костей</a> или <a class=\"item-link quicklink link--popup item-link--class_\" data-key=\"class_/39\" href=\"https://pf2.ru/classes/wizard?tab=details\">волшебник</a> школы <a class=\"item-link quicklink item-link--wizardarcaneschool\" data-key=\"wizardarcaneschool/7\" href=\"https://pf2.ru/wizardarcaneschools/necromancy\">некромантии</a>",
